SET data = json_patch(data, '{
  "coming_soon": null,
  "source_note": null,
  "duration_minutes": 45,
  "outcome_codes": ["EN2-CWT-01"],
  "child_mission": "Become a Sentence Builder. Learn what a sentence needs, then write clear sentences that start with a capital letter, make complete sense and end with the right punctuation.",
  "learning_intention": "We are learning to write clear sentences that make complete sense.",
  "success_criteria": ["I can explain what a sentence is.","I can find who or what the sentence is about and what they did.","I can start a sentence with a capital letter and end it with a full stop, question mark or exclamation mark.","I can fix a fragment so it is a complete sentence.","I can fix a run-on sentence by splitting it or joining it clearly.","I can add detail that tells when, where or how.","I can read my sentence aloud and check that it makes sense."],
  "materials": ["This lesson, with everything you need inside it","A pencil and paper or an exercise book","A quiet spot to read your sentences aloud","Optional: a parent or sibling to listen to your sentences"],
  "teach_steps": [
    {"icon":"✏️","title":"What is a sentence?","explain":"A sentence is a group of words that tells one complete idea. When you read a sentence, you should not be left asking, what happened? or who?\n\nA clear sentence has three things. It tells us who or what the sentence is about. It tells us what they did or what they are like. And it makes complete sense on its own. A sentence also starts with a capital letter and ends with a full stop, a question mark or an exclamation mark.","visual_before":{"svg":"<svg viewBox=\"0 0 720 245\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\"><style>@media (prefers-reduced-motion:reduce){animate{display:none}}.a{font-family:Arial,sans-serif;font-weight:700}.small{font:16px Arial,sans-serif;fill:#334155}</style><rect width=\"720\" height=\"245\" rx=\"20\" fill=\"#eff6ff\"/><text x=\"360\" y=\"38\" text-anchor=\"middle\" class=\"a\" font-size=\"24\" fill=\"#1e3a8a\">A clear sentence tells one complete idea</text><g><rect x=\"72\" y=\"83\" width=\"105\" height=\"64\" rx=\"12\" fill=\"#dbeafe\"/><text x=\"124\" y=\"121\" text-anchor=\"middle\" class=\"a\" font-size=\"23\" fill=\"#1e40af\">The girl</text><animate attributeName=\"opacity\" values=\"0;1;1\" dur=\"5s\" repeatCount=\"indefinite\"/></g><g><rect x=\"194\" y=\"83\" width=\"245\" height=\"64\" rx=\"12\" fill=\"#ffedd5\"/><text x=\"316\" y=\"121\" text-anchor=\"middle\" class=\"a\" font-size=\"23\" fill=\"#9a3412\">kicked the ball</text><animate attributeName=\"opacity\" values=\"0;0;1;1\" keyTimes=\"0;.18;.32;1\" dur=\"5s\" repeatCount=\"indefinite\"/></g><g><circle cx=\"470\" cy=\"115\" r=\"25\" fill=\"#ede9fe\"/><text x=\"470\" y=\"124\" text-anchor=\"middle\" class=\"a\" font-size=\"32\" fill=\"#5b21b6\">.</text><animate attributeName=\"opacity\" values=\"0;0;0;1;1\" keyTimes=\"0;.38;.52;.64;1\" dur=\"5s\" repeatCount=\"indefinite\"/></g><g class=\"small\"><text x=\"124\" y=\"180\" text-anchor=\"middle\">Who or what?</text><text x=\"316\" y=\"180\" text-anchor=\"middle\">Did what?</text><text x=\"470\" y=\"180\" text-anchor=\"middle\">End mark</text></g><text x=\"360\" y=\"221\" text-anchor=\"middle\" class=\"small\">Read it aloud: it should feel finished.</text></svg>","alt":"Animated sentence builder showing The girl, kicked the ball, and a full stop arriving one part at a time.","caption":"A sentence needs someone or something, what happened, and an end mark."},"example":"The girl kicked the ball.\nThis is a sentence. Who? The girl. What did she do? Kicked the ball. It starts with a capital letter and ends with a full stop.","notice":"Your pet says: Read it aloud. Does it feel finished, or are you waiting for more words?","check":{"question":"What does a sentence need?","options":["A picture and a title","Who or what it is about and what they did, so it makes complete sense","Three long words"],"correct_index":1,"explanation":"A sentence tells one complete idea. It needs someone or something and what they did or what they are like."}},
    {"icon":"🔎","title":"Who or what? Doing what?","explain":"To check a sentence, ask two questions. The first is: who or what is this about? The answer is the naming part. The second is: what did they do, or what are they like? The answer is the doing part. Verbs are doing words such as run, jump, laugh, eat and sleep. Some verbs tell us about being, such as is, are and was.\n\nIf you can answer both questions, you probably have a sentence. If one answer is missing, the sentence is not finished.","visual":{"svg":"<svg viewBox=\"0 0 720 265\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\"><style>@media (prefers-reduced-motion:reduce){animate{display:none}}.a{font-family:Arial,sans-serif;font-weight:700}.b{font:17px Arial,sans-serif;fill:#334155}</style><rect width=\"720\" height=\"265\" rx=\"20\" fill=\"#f8fafc\"/><text x=\"360\" y=\"38\" text-anchor=\"middle\" class=\"a\" font-size=\"24\" fill=\"#1f2937\">Ask two questions</text><rect x=\"55\" y=\"72\" width=\"270\" height=\"120\" rx=\"18\" fill=\"#dbeafe\"/><text x=\"190\" y=\"110\" text-anchor=\"middle\" class=\"a\" font-size=\"25\" fill=\"#1e40af\">WHO or WHAT?</text><text x=\"190\" y=\"145\" text-anchor=\"middle\" class=\"a\" font-size=\"23\" fill=\"#1e40af\">The birds</text><rect x=\"395\" y=\"72\" width=\"270\" height=\"120\" rx=\"18\" fill=\"#ffedd5\"/><text x=\"530\" y=\"110\" text-anchor=\"middle\" class=\"a\" font-size=\"25\" fill=\"#9a3412\">DID WHAT?</text><text x=\"530\" y=\"145\" text-anchor=\"middle\" class=\"a\" font-size=\"23\" fill=\"#9a3412\">sang loudly</text><path d=\"M337 132h45\" stroke=\"#64748b\" stroke-width=\"5\" stroke-linecap=\"round\"><animate attributeName=\"stroke-dasharray\" values=\"0 60;60 0;60 0\" dur=\"2.4s\" repeatCount=\"indefinite\"/></path><text x=\"360\" y=\"235\" text-anchor=\"middle\" class=\"b\">Blue names who or what. Orange tells what happened.</text></svg>","alt":"Two large question cards: WHO or WHAT? The birds. DID WHAT? sang loudly.","caption":"Find both parts before you decide that a group of words is a sentence."},"example":"My brother baked a cake.\nWho? My brother. Did what? Baked a cake.\n\nThe puppy is tiny.\nWho? The puppy. What is it like? Tiny.","notice":"Common mistake: writing a long group of describing words and forgetting the doing word. The big brown fluffy dog is not finished.","check":{"question":"In the sentence The birds sang loudly, what is the doing word?","options":["The","sang","loudly"],"correct_index":1,"explanation":"Sang tells us what the birds did. It is the verb."}},
    {"icon":"🔤","title":"Capital letters and end marks","explain":"Every sentence begins with a capital letter. This tells the reader a new idea is starting. Names of people and places also have capital letters, and so does the word I.\n\nEvery sentence ends with an end mark. A full stop ends a statement. A question mark ends a question. An exclamation mark ends a sentence that shows strong feeling, such as surprise or alarm. Choose the end mark that matches what you mean.","visual":{"svg":"<svg viewBox=\"0 0 720 300\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\"><style>@media (prefers-reduced-motion:reduce){animate{display:none}}.a{font-family:Arial,sans-serif;font-weight:700}.b{font:18px Arial,sans-serif;fill:#334155}</style><rect width=\"720\" height=\"300\" rx=\"20\" fill=\"#fff7ed\"/><text x=\"360\" y=\"37\" text-anchor=\"middle\" class=\"a\" font-size=\"24\" fill=\"#9a3412\">Choose the end mark that matches your meaning</text><g><rect x=\"65\" y=\"70\" width=\"180\" height=\"160\" rx=\"16\" fill=\"#fff\" stroke=\"#fdba74\" stroke-width=\"3\"/><text x=\"155\" y=\"116\" text-anchor=\"middle\" class=\"a\" font-size=\"55\" fill=\"#ea580c\">.</text><text x=\"155\" y=\"160\" text-anchor=\"middle\" class=\"a\" font-size=\"20\">Statement</text><text x=\"155\" y=\"194\" text-anchor=\"middle\" class=\"b\">We went to the beach.</text></g><g><rect x=\"270\" y=\"70\" width=\"180\" height=\"160\" rx=\"16\" fill=\"#fff\" stroke=\"#60a5fa\" stroke-width=\"3\"/><text x=\"360\" y=\"116\" text-anchor=\"middle\" class=\"a\" font-size=\"55\" fill=\"#2563eb\">?</text><text x=\"360\" y=\"160\" text-anchor=\"middle\" class=\"a\" font-size=\"20\">Question</text><text x=\"360\" y=\"194\" text-anchor=\"middle\" class=\"b\">Did you bring a towel?</text></g><g><rect x=\"475\" y=\"70\" width=\"180\" height=\"160\" rx=\"16\" fill=\"#fff\" stroke=\"#c084fc\" stroke-width=\"3\"/><text x=\"565\" y=\"116\" text-anchor=\"middle\" class=\"a\" font-size=\"55\" fill=\"#7c3aed\">!</text><text x=\"565\" y=\"160\" text-anchor=\"middle\" class=\"a\" font-size=\"20\">Strong feeling</text><text x=\"565\" y=\"194\" text-anchor=\"middle\" class=\"b\">Watch out for the wave!</text><animateTransform attributeName=\"transform\" type=\"scale\" values=\"1;1.06;1\" dur=\"1.5s\" repeatCount=\"indefinite\" additive=\"sum\"/></g><text x=\"360\" y=\"272\" text-anchor=\"middle\" class=\"b\">Every sentence starts with a capital letter.</text></svg>","alt":"A visual guide showing full stop for a statement, question mark for a question and exclamation mark for strong feeling.","caption":"Start with a capital letter. Match the end mark to the sentence."},"example":"We went to the beach.\nDid you bring a towel?\nWatch out for the wave!\nThree sentences. Each starts with a capital letter. Each ends with a different end mark.","notice":"Your pet says: Check the first letter and the last mark every time. Those two are the easiest to forget.","check":{"question":"Which end mark belongs at the end of: Where is my hat","options":["A full stop","A question mark","A comma"],"correct_index":1,"explanation":"The sentence asks something, so it ends with a question mark."}},
    {"icon":"🧩","title":"Fixing fragments","explain":"A fragment is a group of words that is missing something. It might be missing who or what, or it might be missing what they did. It does not make complete sense on its own.\n\nTo fix a fragment, ask what is missing and add it. Then check that the sentence is complete. Fragments are sometimes used by writers on purpose, but in your own clear sentences you should write the full idea.","visual":{"svg":"<svg viewBox=\"0 0 720 265\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\"><style>@media (prefers-reduced-motion:reduce){animate{display:none}}.a{font-family:Arial,sans-serif;font-weight:700}.b{font:18px Arial,sans-serif;fill:#334155}</style><rect width=\"720\" height=\"265\" rx=\"20\" fill=\"#fef2f2\"/><text x=\"360\" y=\"37\" text-anchor=\"middle\" class=\"a\" font-size=\"24\" fill=\"#991b1b\">A fragment is missing a piece</text><rect x=\"65\" y=\"77\" width=\"235\" height=\"78\" rx=\"12\" fill=\"#fee2e2\" stroke=\"#dc2626\" stroke-width=\"3\" stroke-dasharray=\"8 6\"/><text x=\"182\" y=\"122\" text-anchor=\"middle\" class=\"a\" font-size=\"25\" fill=\"#991b1b\">Ran down the hill.</text><text x=\"182\" y=\"184\" text-anchor=\"middle\" class=\"b\">Who ran?</text><path d=\"M323 116h72\" stroke=\"#16a34a\" stroke-width=\"6\" stroke-linecap=\"round\"><animate attributeName=\"stroke-dasharray\" values=\"0 80;80 0;80 0\" dur=\"2.8s\" repeatCount=\"indefinite\"/></path><rect x=\"418\" y=\"77\" width=\"237\" height=\"78\" rx=\"12\" fill=\"#dcfce7\"/><text x=\"536\" y=\"122\" text-anchor=\"middle\" class=\"a\" font-size=\"23\" fill=\"#166534\">The boy ran down the hill.</text><text x=\"536\" y=\"184\" text-anchor=\"middle\" class=\"b\">Complete sentence</text><text x=\"360\" y=\"235\" text-anchor=\"middle\" class=\"b\">Add the missing who or what, or add what happened.</text></svg>","alt":"A fragment, Ran down the hill, changes into the complete sentence, The boy ran down the hill.","caption":"Fix a fragment by adding the missing part."},"example":"Fragment: Ran down the hill.\nWho ran? Nothing tells us. Fixed: The boy ran down the hill.\n\nFragment: The big brown dog.\nWhat did it do? Nothing tells us. Fixed: The big brown dog barked at the postie.","notice":"Common mistake: thinking a long group of words must be a sentence. Long does not mean complete.","check":{"question":"Which one is a complete sentence?","options":["Ran down the hill.","The girl ran down the hill.","The girl down the hill."],"correct_index":1,"explanation":"The girl ran down the hill. tells who and what she did, so it is complete."}},
    {"icon":"🚂","title":"Fixing run-on sentences","explain":"A run-on sentence squashes two or more ideas together with no clear break. The reader does not know where one idea ends and the next begins.\n\nYou can fix a run-on in two ways. You can split it into separate sentences with capital letters and end marks. Or you can join the ideas with a joining word such as and, but, so or because, and a comma if it helps. Read it aloud to hear where you naturally stop.","visual":{"svg":"<svg viewBox=\"0 0 720 290\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\"><style>@media (prefers-reduced-motion:reduce){animate{display:none}}.a{font-family:Arial,sans-serif;font-weight:700}.b{font:17px Arial,sans-serif;fill:#334155}</style><rect width=\"720\" height=\"290\" rx=\"20\" fill=\"#fff7ed\"/><text x=\"360\" y=\"37\" text-anchor=\"middle\" class=\"a\" font-size=\"24\" fill=\"#9a3412\">A run-on sentence needs clear stops</text><rect x=\"54\" y=\"66\" width=\"612\" height=\"52\" rx=\"12\" fill=\"#fee2e2\"/><text x=\"360\" y=\"99\" text-anchor=\"middle\" class=\"a\" font-size=\"19\" fill=\"#991b1b\">The dog barked the cat ran away the boy laughed.</text><path d=\"M170 133v45m180-45v45m175-45v45\" stroke=\"#ea580c\" stroke-width=\"5\" stroke-linecap=\"round\" stroke-dasharray=\"7 7\"><animate attributeName=\"stroke-dashoffset\" values=\"0;-28\" dur=\"1.4s\" repeatCount=\"indefinite\"/></path><g><rect x=\"54\" y=\"196\" width=\"184\" height=\"50\" rx=\"10\" fill=\"#dcfce7\"/><text x=\"146\" y=\"227\" text-anchor=\"middle\" class=\"a\" font-size=\"16\" fill=\"#166534\">The dog barked.</text><rect x=\"268\" y=\"196\" width=\"184\" height=\"50\" rx=\"10\" fill=\"#dcfce7\"/><text x=\"360\" y=\"227\" text-anchor=\"middle\" class=\"a\" font-size=\"16\" fill=\"#166534\">The cat ran away.</text><rect x=\"482\" y=\"196\" width=\"184\" height=\"50\" rx=\"10\" fill=\"#dcfce7\"/><text x=\"574\" y=\"227\" text-anchor=\"middle\" class=\"a\" font-size=\"16\" fill=\"#166534\">The boy laughed.</text></g><text x=\"360\" y=\"275\" text-anchor=\"middle\" class=\"b\">Split the ideas, or connect them with a joining word.</text></svg>","alt":"A run-on sentence is split into three separate sentence cards, each with a full stop.","caption":"Let the reader see where one idea ends and the next one begins."},"example":"Run-on: The dog barked the cat ran away the boy laughed.\nFix 1 (split): The dog barked. The cat ran away. The boy laughed.\nFix 2 (join): The dog barked, and the cat ran away. The boy laughed.","notice":"Your pet says: When you take a breath while reading aloud, that is often where a sentence ends.","check":{"question":"Which is the best fix for: The rain stopped we went outside","options":["The rain stopped, so we went outside.","The rain stopped we went outside.","The rain stopped we, went outside."],"correct_index":0,"explanation":"The joining word so, with a comma, shows how the two ideas are connected."}},
    {"icon":"🌈","title":"Adding clear detail","explain":"A short sentence is fine, but detail helps the reader see what you mean. You can add detail by answering when, where, how or what kind.\n\nStart with a simple sentence and add one piece of detail at a time. Make sure each new word helps the reader. Too many describing words can make a sentence messy, so read it back to check that it is still clear.","visual":{"svg":"<svg viewBox=\"0 0 720 305\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\"><style>@media (prefers-reduced-motion:reduce){animate{display:none}}.a{font-family:Arial,sans-serif;font-weight:700}.b{font:18px Arial,sans-serif;fill:#334155}</style><rect width=\"720\" height=\"305\" rx=\"20\" fill=\"#f0fdf4\"/><text x=\"360\" y=\"35\" text-anchor=\"middle\" class=\"a\" font-size=\"24\" fill=\"#166534\">Add one helpful detail at a time</text><g><text x=\"75\" y=\"89\" class=\"a\" font-size=\"20\" fill=\"#334155\">Start</text><rect x=\"165\" y=\"60\" width=\"160\" height=\"44\" rx=\"9\" fill=\"#e5e7eb\"/><text x=\"245\" y=\"89\" text-anchor=\"middle\" class=\"a\" font-size=\"20\">The dog ran.</text></g><g><text x=\"75\" y=\"151\" class=\"a\" font-size=\"20\" fill=\"#334155\">Where?</text><rect x=\"165\" y=\"122\" width=\"315\" height=\"44\" rx=\"9\" fill=\"#dbeafe\"/><text x=\"322\" y=\"151\" text-anchor=\"middle\" class=\"a\" font-size=\"19\" fill=\"#1e40af\">The dog ran across the park.</text></g><g><text x=\"75\" y=\"213\" class=\"a\" font-size=\"20\" fill=\"#334155\">When?</text><rect x=\"165\" y=\"184\" width=\"420\" height=\"44\" rx=\"9\" fill=\"#ffedd5\"/><text x=\"375\" y=\"213\" text-anchor=\"middle\" class=\"a\" font-size=\"18\" fill=\"#9a3412\">After lunch, the dog ran across the park.</text></g><g><text x=\"75\" y=\"275\" class=\"a\" font-size=\"20\" fill=\"#334155\">What kind?</text><rect x=\"165\" y=\"246\" width=\"492\" height=\"44\" rx=\"9\" fill=\"#ede9fe\"/><text x=\"411\" y=\"275\" text-anchor=\"middle\" class=\"a\" font-size=\"17\" fill=\"#5b21b6\">After lunch, the brown dog ran across the park.</text><animate attributeName=\"opacity\" values=\".35;1;.35\" dur=\"2s\" repeatCount=\"indefinite\"/></g></svg>","alt":"A sentence grows from The dog ran to After lunch, the brown dog ran across the park as useful details are added.","caption":"Ask when, where, how or what kind. Add only details that help the reader."},"example":"Start: The dog ran.\nWhere? The dog ran across the park.\nWhen? After lunch, the dog ran across the park.\nWhat kind? After lunch, the brown dog ran across the park.","notice":"Common mistake: adding so many words that the main idea gets lost. Add detail one piece at a time.","check":{"question":"Which sentence has the most useful detail?","options":["The dog ran.","The brown dog ran across the park after lunch.","The dog ran ran ran."],"correct_index":1,"explanation":"It tells what kind of dog, where it ran and when, and it is still clear."}},
    {"icon":"👂","title":"Check it: read it aloud","explain":"Good writers check their sentences. Read each sentence aloud, slowly, then use a three-point check. First, capital letter at the start and an end mark at the finish. Second, who or what and what they did. Third, does it make complete sense on its own?\n\nIf the answer to any check is no, fix it, then read it again. Fixing your own work is part of writing, not a mistake.","visual":{"svg":"<svg viewBox=\"0 0 720 280\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\"><style>@media (prefers-reduced-motion:reduce){animate{display:none}}.a{font-family:Arial,sans-serif;font-weight:700}.b{font:18px Arial,sans-serif;fill:#334155}</style><rect width=\"720\" height=\"280\" rx=\"20\" fill=\"#f5f3ff\"/><text x=\"360\" y=\"38\" text-anchor=\"middle\" class=\"a\" font-size=\"24\" fill=\"#5b21b6\">The three-point sentence check</text><g><circle cx=\"120\" cy=\"135\" r=\"48\" fill=\"#dbeafe\"/><text x=\"120\" y=\"128\" text-anchor=\"middle\" class=\"a\" font-size=\"19\" fill=\"#1e40af\">1</text><text x=\"120\" y=\"153\" text-anchor=\"middle\" class=\"a\" font-size=\"15\" fill=\"#1e40af\">Capital +</text><text x=\"120\" y=\"174\" text-anchor=\"middle\" class=\"a\" font-size=\"15\" fill=\"#1e40af\">end mark</text></g><g><circle cx=\"360\" cy=\"135\" r=\"48\" fill=\"#ffedd5\"/><text x=\"360\" y=\"128\" text-anchor=\"middle\" class=\"a\" font-size=\"19\" fill=\"#9a3412\">2</text><text x=\"360\" y=\"153\" text-anchor=\"middle\" class=\"a\" font-size=\"15\" fill=\"#9a3412\">Who or what?</text><text x=\"360\" y=\"174\" text-anchor=\"middle\" class=\"a\" font-size=\"15\" fill=\"#9a3412\">Did what?</text></g><g><circle cx=\"600\" cy=\"135\" r=\"48\" fill=\"#dcfce7\"/><text x=\"600\" y=\"128\" text-anchor=\"middle\" class=\"a\" font-size=\"19\" fill=\"#166534\">3</text><text x=\"600\" y=\"153\" text-anchor=\"middle\" class=\"a\" font-size=\"15\" fill=\"#166534\">Makes</text><text x=\"600\" y=\"174\" text-anchor=\"middle\" class=\"a\" font-size=\"15\" fill=\"#166534\">sense?</text></g><path d=\"M176 135h125m118 0h125\" stroke=\"#7c3aed\" stroke-width=\"5\" stroke-linecap=\"round\" stroke-dasharray=\"10 8\"><animate attributeName=\"stroke-dashoffset\" values=\"0;-36\" dur=\"1.2s\" repeatCount=\"indefinite\"/></path><text x=\"360\" y=\"245\" text-anchor=\"middle\" class=\"b\">Read it aloud, fix one thing, then read it again.</text></svg>","alt":"Three connected circles show the sentence check: 1 capital letter and end mark, 2 who or what and did what, 3 makes sense.","caption":"Use this quick check every time you finish a sentence."},"example":"Draft: after school we played\nCheck 1: no capital letter, no end mark. Check 2: who is we, what did we do: played. Check 3: played what, where? Improved: After school, we played cricket in the yard.","notice":"Your pet says: Your first draft does not have to be perfect. Checking is how writers get better.","check":{"question":"What is the best last step when you write a sentence?","options":["Read it aloud and check it","Make it as long as possible","Never look at it again"],"correct_index":0,"explanation":"Reading aloud helps you hear what is missing or unclear."}}
  ],
  "explicit_teaching": "Parent: This lesson teaches the basic building block of writing, the complete sentence. At this age, children often write fragments or run-ons because they write the way they speak. The goal is not fancy sentences. It is sentences that are clear, complete and correctly marked.\n\nTeach with a simple routine: who or what, did what, makes sense, capital letter, end mark. Model it on one sentence first, then let your child try. Keep the language simple. Use the words sentence, fragment and run-on, but do not worry if they only remember sentence and complete.\n\nCorrect gently. Ask a question rather than telling: Who ran? or Where did the sentence stop? Praise one thing they did well before you point out one thing to fix.\n\nIf your child finds writing hard, let them say the sentence first, then write it. If they are confident, ask for detail: when, where, how.",
  "worked_example": "Example 1: The girl kicked the ball.\nWho? The girl. Did what? Kicked the ball. Capital letter and full stop: yes. Result: a complete sentence.\n\nExample 2: Ran across the road.\nWho ran? Missing. Fix: The cat ran across the road. Common mistake: starting with a doing word and forgetting who did it.\n\nExample 3: The big green frog.\nDid what? Missing. Fix: The big green frog jumped into the pond. Common mistake: only describing the thing.\n\nExample 4: We went to the park we played on the swings.\nTwo ideas run together. Fix 1: We went to the park. We played on the swings. Fix 2: We went to the park, and we played on the swings.\n\nExample 5: Did you see that\nIt asks something, so it needs a question mark. Fix: Did you see that? Common mistake: using a full stop for a question.\n\nExample 6: Draft: the dog ran. Improved: After lunch, the brown dog ran across the park.\nDetail added one piece at a time: when (after lunch), what kind (brown), where (across the park). Capital letters and end mark checked.",
  "worked_visuals": [{"svg":"<svg viewBox=\"0 0 720 240\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\"><style>@media (prefers-reduced-motion:reduce){animate{display:none}}.a{font-family:Arial,sans-serif;font-weight:700}.b{font:18px Arial,sans-serif;fill:#334155}</style><rect width=\"720\" height=\"240\" rx=\"20\" fill=\"#f8fafc\"/><text x=\"360\" y=\"35\" text-anchor=\"middle\" class=\"a\" font-size=\"24\" fill=\"#1f2937\">Build a stronger sentence, one detail at a time</text><rect x=\"55\" y=\"65\" width=\"610\" height=\"52\" rx=\"10\" fill=\"#e5e7eb\"/><text x=\"360\" y=\"99\" text-anchor=\"middle\" class=\"a\" font-size=\"23\">The dog ran.</text><path d=\"M360 122v20\" stroke=\"#64748b\" stroke-width=\"5\"/><polygon points=\"350,139 370,139 360,153\" fill=\"#64748b\"/><rect x=\"55\" y=\"157\" width=\"610\" height=\"52\" rx=\"10\" fill=\"#ede9fe\"/><text x=\"360\" y=\"191\" text-anchor=\"middle\" class=\"a\" font-size=\"20\" fill=\"#5b21b6\">After lunch, the brown dog ran across the park.</text><circle cx=\"645\" cy=\"182\" r=\"18\" fill=\"#dcfce7\"/><path d=\"M635 182l7 7 13-16\" fill=\"none\" stroke=\"#16a34a\" stroke-width=\"4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><animate attributeName=\"stroke-dasharray\" values=\"0 50;50 0;50 0\" dur=\"2s\" repeatCount=\"indefinite\"/></path><text x=\"360\" y=\"231\" text-anchor=\"middle\" class=\"b\">Useful details help the reader picture what happened.</text></svg>","alt":"A simple sentence transforms into a more detailed sentence, with a green check mark.","caption":"Clear writing does not need to be long. It needs the right details."}],
  "guided_practice": "Part A: Who and what. Write who or what and what they did: The baby laughed at the funny face. Hint: ask the two questions. Answer: Who: the baby. Did what: laughed at the funny face.\n\nPart B: End marks. Add the correct end mark: Where did you put the keys. Answer: Where did you put the keys?\n\nPart C: Fix the fragment. Make this a sentence: Jumped over the log. Answer: any complete sentence with a who, such as The rabbit jumped over the log.\n\nPart D: Fix the fragment. Make this a sentence: The tall old tree. Answer: any complete sentence with an action, such as The tall old tree fell in the storm.\n\nPart E: Fix the run-on by splitting it: The sun came out the children ran to the pool. Answer: The sun came out. The children ran to the pool.\n\nPart F: Fix the run-on by joining it with so, and or but: It was raining we stayed inside. Answer: It was raining, so we stayed inside.\n\nPart G: Add detail. Start with: The bird sang. Add where, when and what kind. Answer: any clear sentence such as In the morning, the little bird sang in the gum tree.\n\nPart H: Check it. Fix this draft with the three-point check: my sister likes pizza. Answer: My sister likes pizza. (capital letter and end mark are the fixes; the sentence is already complete).\n\nParent prompt for every part: Who or what is it about, and what did they do? Pet hint for every part: Read it aloud and listen for what is missing.",
  "independent_task": "Part 1: Sort. For each, write sentence or not a sentence.\n1. The cat sat on the mat.\n2. Under the old bridge.\n3. My mum made dinner.\n4. Laughed and laughed.\n5. The tiny kitten purred.\n\nPart 2: Fix. Rewrite each as a complete sentence with a capital letter and an end mark.\n6. ran to the shops\n7. the happy children\n8. is the bus coming\n9. we saw a big whale it jumped out of the water\n10. in the morning\n\nPart 3: Add detail. Make each sentence better by adding when, where or how.\n11. The boy ran.\n12. The dog slept.\n13. A bird flew.\n\nPart 4: Write your own.\n14. Write three clear sentences about your favourite place. Use a different end mark in at least one sentence.\n15. Read your three sentences aloud. Use the three-point check on each one, then fix anything you find and tick when it is done.",
  "response_prompt": "Write one or two sentences about which part of making a clear sentence was easiest for you today, and which part you want to practise more.",
  "quiz": [{"type":"multiple_choice","question":"What is a sentence?","options":["A group of words that tells one complete idea","Any group of words","A single letter"],"correct_index":0,"explanation":"A sentence tells one complete idea and makes sense on its own."},{"type":"multiple_choice","question":"How should a sentence start and end?","options":["With a small letter and no end mark","With a capital letter and an end mark","With a comma and a capital letter"],"correct_index":1,"explanation":"A sentence begins with a capital letter and ends with a full stop, question mark or exclamation mark."},{"type":"multiple_choice","question":"Which one is a complete sentence?","options":["Ran across the field.","The big brown horse.","The horse ran across the field."],"correct_index":2,"explanation":"It tells who (the horse) and what it did (ran across the field)."},{"type":"multiple_choice","question":"The big brown dog. Why is this a fragment?","options":["It does not say what the dog did","It is too short","It has a capital letter"],"correct_index":0,"explanation":"It only describes the dog. There is no doing word telling what the dog did."},{"type":"multiple_choice","question":"Which is the best fix for: The dog barked the cat ran away","options":["The dog barked, and the cat ran away.","The dog barked the cat ran away.","The dog, barked the cat ran away."],"correct_index":0,"explanation":"The joining word and, with a comma, separates the two ideas clearly."},{"type":"multiple_choice","question":"Which end mark should be at the end of: What time does the movie start","options":["A full stop","An exclamation mark","A question mark"],"correct_index":2,"explanation":"The sentence asks something, so it needs a question mark."},{"type":"multiple_choice","question":"Which sentence has the most useful detail?","options":["The girl sang.","The girl sang sang sang.","The shy girl sang a song at the concert."],"correct_index":2,"explanation":"It tells what kind of girl, what she sang and where, and it is still clear."},{"type":"multiple_choice","question":"What is the best way to check a sentence you wrote?","options":["Read it aloud and use the three-point check","Hand it in without looking","Make it longer"],"correct_index":0,"explanation":"Reading aloud and checking the capital letter, end mark and meaning helps you find mistakes."},{"type":"short_answer","question":"Rewrite this fragment as a complete sentence and explain what you added: Jumped into the pool.","sample_answer":"The boy jumped into the pool. I added who jumped, the boy, so the sentence tells who and what they did.","marking_guide":"Full marks for a complete sentence with a who or what and a correct capital letter and end mark, plus an explanation of what was added. Partial marks for a complete sentence with no explanation."},{"type":"short_answer","question":"Fix this run-on in two different ways: We got home we had dinner we watched a movie.","sample_answer":"We got home. We had dinner. We watched a movie. Or: We got home, and we had dinner. Then we watched a movie.","marking_guide":"Full marks for two different correct fixes, such as splitting and joining, with capital letters and end marks. Partial marks for one correct fix."}],
  "parent_notes": "Keep the lesson calm and short. Ask your child to say each sentence aloud before writing it. If they write a fragment or run-on, ask a question instead of correcting it: Who ran? or Where did your sentence stop? Praise one thing first, such as a good capital letter, then fix one thing at a time. If your child finds handwriting tiring, let them speak the sentence and you write it, then they copy it. For a confident writer, use the detail questions and try the extension. Use the pet hints as prompts to think, not as answers, and use them less as your child grows more confident.",
  "evidence_instructions": "Keep the three sentences from independent task 14 and the notes from your three-point check. A parent can also read the sentences aloud and tick whether each one starts with a capital letter, ends with an end mark, and makes complete sense.",
  "offline_alternative": "Printable activity pack: write or print a Sentence Check Card with columns for capital letter, who or what, did what, end mark and makes sense. Print the five Part 1 groups for a sentence/not-a-sentence sorting activity. Print Part 2 as a fix-it worksheet, and make a detail ladder with boxes for when, where and what kind. Include answers for the parent: Part 1 is sentence, not a sentence, sentence, not a sentence, sentence. For Part 2 and Part 3, accept any clear, complete sentence with the needed correction or detail.",
  "extension": "Write a short paragraph of five clear sentences about something that happened this week. Use at least one question and one exclamation. Then swap with someone, and see if they can find where each sentence starts and ends."
}')
WHERE seed_key = 's2-eng-y3-w01-l2';
